import type { Metadata } from 'next'
import { createClient } from '@/lib/supabase/server'
import { redirect, notFound } from 'next/navigation'
import { SubmissionView } from '@/components/consent/submissions/SubmissionView'

export const metadata: Metadata = {
  title: 'Submission — InkOS',
}

interface PageProps {
  params: Promise<{ id: string }>
}

export default async function SubmissionPage({ params }: PageProps) {
  const { id } = await params

  const supabase = await createClient()
  const {
    data: { user },
  } = await supabase.auth.getUser()
  if (!user) redirect('/login')

  // Verify the submission belongs to this user's studio (basic auth check)
  const { data, error } = await supabase
    .from('consent_form_submissions')
    .select('id')
    .eq('id', id)
    .single()

  if (error || !data) notFound()

  return (
    <div className="flex h-[calc(100dvh-56px)] flex-col overflow-hidden">
      <SubmissionView submissionId={id} />
    </div>
  )
}
