import type { Metadata } from 'next'
import { PortfolioComingSoon } from '@/components/portfolio/PortfolioComingSoon'

export const metadata: Metadata = {
  title: 'Flash & Portfolio — InkOS',
}

export default function PortfolioPage() {
  return <PortfolioComingSoon />
}

'use client'

import { useState } from 'react'
import { Image as ImageIcon } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { toast } from 'sonner'

/**
 * S17 — Polished coming-soon empty state for /portfolio.
 * Roadmapped for Sprint S18.
 */
export function PortfolioComingSoon() {
  const [loading, setLoading] = useState(false)
  const [notified, setNotified] = useState(false)

  async function handleNotify() {
    setLoading(true)
    try {
      await fetch('/api/feature-interest', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ feature: 'portfolio' }),
      })
      setNotified(true)
      toast.success("We'll let you know when Flash & Portfolio ships")
    } catch {
      toast.error('Something went wrong. Try again.')
    } finally {
      setLoading(false)
    }
  }

  return (
    <div className="flex min-h-[60vh] flex-col items-center justify-center px-6 text-center">
      <div className="mb-6 flex h-16 w-16 items-center justify-center rounded-2xl bg-primary/10">
        <ImageIcon className="h-8 w-8 text-primary" aria-hidden="true" />
      </div>
      <h1 className="mb-2 text-2xl font-bold tracking-tight text-foreground">
        Flash &amp; Portfolio
      </h1>
      <p className="mb-1 max-w-md text-sm text-muted-foreground">
        Share your studio&apos;s work with clients — upload flash, showcase artist portfolios, and build a public gallery.
      </p>
      <p className="mb-4 max-w-md text-xs text-muted-foreground/60">
        Planned features: flash sheet uploads, per-artist galleries, public embeddable gallery link, and client favorites.
      </p>
      <p className="mb-8 text-xs text-muted-foreground/60">
        Coming in Sprint S18
      </p>
      {notified ? (
        <p className="rounded-lg border border-emerald-500/30 bg-emerald-500/10 px-4 py-2 text-sm font-medium text-emerald-600 dark:text-emerald-400">
          You&apos;re on the list
        </p>
      ) : (
        <Button
          variant="outline"
          onClick={() => void handleNotify()}
          disabled={loading}
        >
          {loading ? 'Saving...' : 'Notify me when it ships'}
        </Button>
      )}
    </div>
  )
}

