import { useState } from 'react'
import Link from 'next/link'
import { ArrowLeft, Image as ImageIcon, LayoutGrid, Share2, Sparkles } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { toast } from 'sonner'

/**
 * S18 — Polished empty state for /portfolio.
 * Real portfolio build (tabs, upload, public galleries) deferred to S19.
 */
export function PortfolioComingSoon() {
  const [loading, setLoading] = useState(false)
  const [notified, setNotified] = useState(false)

  async function handleNotify() {
    setLoading(true)
    try {
      await fetch('/api/feature-interest', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ feature: 'portfolio' }),
      })
      setNotified(true)
      toast.success("We'll let you know when Flash & Portfolio ships")
    } catch {
      toast.error('Something went wrong. Try again.')
    } finally {
      setLoading(false)
    }
  }

  return (
    <div className="flex min-h-[calc(100vh-4rem)] flex-col px-6 py-8">
      <div className="mx-auto flex w-full max-w-2xl flex-1 flex-col items-center justify-center text-center">
        {/* Icon tile */}
        <div className="mb-6 flex h-16 w-16 items-center justify-center rounded-2xl bg-primary/10 shadow-[var(--shadow-soft)]">
          <ImageIcon className="h-8 w-8 text-primary" aria-hidden="true" />
        </div>

        {/* Headline */}
        <h1 className="mb-3 text-3xl font-bold tracking-tight text-foreground">
          Flash &amp; Portfolio
        </h1>
        <p className="mb-8 max-w-md text-sm text-muted-foreground">
          Share your studio&apos;s work with clients — upload flash sheets,
          showcase artist portfolios, and build a public gallery.
        </p>

        {/* Feature teasers */}
        <div className="mb-10 grid w-full max-w-xl grid-cols-1 gap-3 sm:grid-cols-3">
          <FeatureTeaser
            icon={ImageIcon}
            title="Flash sheets"
            description="Upload available flash, price each piece, mark as sold."
          />
          <FeatureTeaser
            icon={LayoutGrid}
            title="Artist galleries"
            description="Per-artist portfolios grouped by style and placement."
          />
          <FeatureTeaser
            icon={Share2}
            title="Public URLs"
            description="Shareable gallery links for Instagram bio and DMs."
          />
        </div>

        {/* Status pill */}
        <div className="mb-4 inline-flex items-center gap-1.5 rounded-full border border-primary/20 bg-primary/5 px-3 py-1 text-[11px] font-semibold uppercase tracking-wide text-primary">
          <Sparkles className="h-3 w-3" aria-hidden="true" />
          Launching in Sprint S19
