function DropdownMenuLabel({
  className,
  inset,
  ...props
}: MenuPrimitive.GroupLabel.Props & {
  inset?: boolean
}) {
  // Base UI's MenuGroupLabel throws error #31 ("MenuGroupRootContext is missing.
  // Menu group parts must be used within <Menu.Group>.") when mounted outside a
  // Menu.Group. All 5 call sites of DropdownMenuLabel in this repo use it as a
  // visual heading rather than a semantic group label, so we wrap the label in
  // a tiny <MenuPrimitive.Group> here — fixing every caller at once without
  // forcing each one to add a DropdownMenuGroup wrapper.
  return (
    <MenuPrimitive.Group>
      <MenuPrimitive.GroupLabel
        data-slot="dropdown-menu-label"
        data-inset={inset}
        className={cn(
          "px-1.5 py-1 text-xs font-medium text-muted-foreground data-inset:pl-7",
          className
        )}
        {...props}
      />
    </MenuPrimitive.Group>
  )
}

