function buildTrail(
  path: string,
  tab: string | null,
  dynamicLabels: Record<string, string>,
  { rootLabel, rootHref }: BuildTrailOptions,
): Crumb[] {
  const crumbs: Crumb[] = [{ label: rootLabel, href: rootHref }]

  const segments = path.split('/').filter(Boolean)
  // Skip the root segment if it matches the root href (e.g., "admin" when rootHref="/admin")
  const rootSegments = rootHref.split('/').filter(Boolean)
  const relativeSegments = segments.slice(rootSegments.length)

  let built = rootHref
