import type { Metadata } from 'next'
import { redirect } from 'next/navigation'
import { createClient } from '@/lib/supabase/server'
import { TodayClient } from '@/components/today/TodayClient'
import { ArtistTodayDashboard } from '@/components/today/ArtistTodayDashboard'
import type { GettingStartedCounts } from '@/components/dashboard/GettingStartedCard'
import { getArtistIdForUser, getArtistEarningsToday } from '@/lib/today/queries'
import type { Database } from '@/lib/supabase/types'

export const metadata: Metadata = {
  title: 'Today — InkOS',
}

type StudioRole = Database['public']['Tables']['studio_members']['Row']['role']

export default async function TodayPage() {
  const supabase = await createClient()
  const {
    data: { user },
  } = await supabase.auth.getUser()

  if (!user) redirect('/login')

  const [profileResult, memberResult] = await Promise.all([
    supabase
      .from('profiles')
      .select('full_name')
      .eq('id', user.id)
      .single(),
    supabase
      .from('studio_members')
      .select('studio_id, role, studios(name)')
      .eq('user_id', user.id)
      .is('deactivated_at', null)
      .order('created_at', { ascending: true })
      .limit(1)
      .single(),
  ])

  const firstName = profileResult.data?.full_name?.split(' ')[0] ?? 'there'
  const studioName =
    (memberResult.data?.studios as { name: string } | null)?.name ?? 'My Studio'
  const hasStudio = !!memberResult.data?.studio_id
  const studioId = memberResult.data?.studio_id
  const role: StudioRole = memberResult.data?.role ?? 'owner'

  let gettingStartedCounts: GettingStartedCounts = {
    services: 0,
    artists: 0,
    schedules: 0,
    bookings: 0,
    bookingPageConfigured: false,
  }

  let ownArtistId: string | null = null
  let artistEarningsToday = 0

  if (studioId) {
    const [servicesRes, artistsRes, schedulesRes, bookingsRes, bpRes] = await Promise.all([
      supabase
        .from('services')
        .select('id', { count: 'exact', head: true })
        .eq('studio_id', studioId),
      supabase
        .from('artists')
        .select('id', { count: 'exact', head: true })
        .eq('studio_id', studioId),
      supabase
        .from('artist_schedules')
        .select('id', { count: 'exact', head: true })
        .eq('studio_id', studioId),
      supabase
        .from('bookings')
        .select('id', { count: 'exact', head: true })
        .eq('studio_id', studioId),
      supabase
        .from('booking_page_settings')
        .select('studio_id', { count: 'exact', head: true })
        .eq('studio_id', studioId),
    ])

    gettingStartedCounts = {
      services: servicesRes.count ?? 0,
      artists: artistsRes.count ?? 0,
      schedules: schedulesRes.count ?? 0,
      bookings: bookingsRes.count ?? 0,
      bookingPageConfigured: (bpRes.count ?? 0) > 0,
    }

    if (role === 'artist' || role === 'guest_artist') {
      ownArtistId = await getArtistIdForUser(supabase, studioId, user.id)
      if (ownArtistId) {
        artistEarningsToday = await getArtistEarningsToday(supabase, studioId, ownArtistId)
      }
    }
  }

  // S19: artist and guest_artist roles see their personal artist dashboard
  if ((role === 'artist' || role === 'guest_artist') && studioId && ownArtistId) {
    return (
      <ArtistTodayDashboard
        firstName={firstName}
        studioId={studioId}
        artistId={ownArtistId}
        artistEarningsToday={artistEarningsToday}
      />
    )
  }

  return (
    <TodayClient
      firstName={firstName}
      studioName={studioName}
      hasStudio={hasStudio}
      studioId={studioId ?? null}
      role={role}
      ownArtistId={ownArtistId}
      artistEarningsToday={artistEarningsToday}
      gettingStartedCounts={gettingStartedCounts}
    />
  )
}

/**
 * Server-side helper to resolve the active studio context for the current user.
 *
 * Resolution order:
 *  1. Cookie `inkos_active_studio` (httpOnly, SameSite=Lax, Max-Age 31536000)
 *  2. First membership ordered by studio_members.created_at ASC
 *
 * URL param `?studio=X` is honoured via <StudioParamSync> client component on mount —
 * it fires a POST to /api/context/set-studio which writes the cookie, then calls
 * router.refresh(). Layout reads only cookie + fallback (no search param in layout).
 *
 * Throws if the user has no studio memberships (caller redirects to /onboarding).
 */

import { cookies } from 'next/headers'
import { createClient } from '@/lib/supabase/server'
import type { Database } from '@/lib/supabase/types'
import type { PlanTier } from '@/lib/billing/feature-gate'

export type StudioRow = Database['public']['Tables']['studios']['Row']
export type StudioMemberRow = Database['public']['Tables']['studio_members']['Row']
export type StudioMemberRole = StudioMemberRow['role']

export interface StudioMembership {
  studioId: string
  studio: StudioRow
  role: StudioMemberRole
  /** Resolved subscription plan for this studio. Defaults 'solo' if no active sub. */
  plan: PlanTier
}

export interface ActiveStudioContext {
  studioId: string
  studio: StudioRow
  role: StudioMemberRole
  plan: PlanTier
  allMemberships: StudioMembership[]
}

export class NoStudioMembershipError extends Error {
  constructor() {
    super('User has no studio memberships')
    this.name = 'NoStudioMembershipError'
  }
}

export async function getActiveStudio(): Promise<ActiveStudioContext> {
  const supabase = await createClient()

  // 1. Identify current user
  const {
    data: { user },
    error: authError,
  } = await supabase.auth.getUser()
  if (authError || !user) {
    throw new NoStudioMembershipError()
  }

  // 2. Fetch all memberships with studio data, ordered by created_at ASC
  const { data: rows, error: memberError } = await supabase
    .from('studio_members')
    .select(
      `
      studio_id,
      role,
      created_at,
      studios (
        id, name, slug, timezone, locale, currency, brand_color, logo_url, plan_id,
        custom_domain, custom_domain_verified, custom_domain_verified_at,
        white_label_enabled, custom_favicon_url, custom_email_from_name,
        custom_email_reply_to, powered_by_hidden, status, created_at, updated_at
      )
      `
    )
    .eq('user_id', user.id)
    .is('deactivated_at', null)
    .order('created_at', { ascending: true })

  if (memberError || !rows || rows.length === 0) {
    throw new NoStudioMembershipError()
  }

  // 3. Resolve plan for each studio (subscription lookup per studio_id)
  //    Use Promise.all with a small batch to avoid N+1 for users with many studios.
  const membershipsWithPlan: (StudioMembership | null)[] = await Promise.all(
    rows.map(async (row) => {
      // Type-safe studio extract — the join shape is deterministic
      const studio = (
        Array.isArray(row.studios) ? row.studios[0] : row.studios
      ) as StudioRow | null

      if (!studio) {
        // Edge: studio row deleted but membership exists — skip gracefully
        return null
      }

      let plan: PlanTier = 'solo'
      const { data: sub } = await supabase
        .from('subscriptions')
        .select('plan_tier')
        .eq('studio_id', row.studio_id)
        .eq('status', 'active')
        .maybeSingle()
      if (sub?.plan_tier) {
        plan = sub.plan_tier as PlanTier
      }

      return {
        studioId: row.studio_id,
        studio,
        role: row.role as StudioMemberRole,
        plan,
      } satisfies StudioMembership
    })
  )

  // Filter out any null slots (deleted studios)
  const validMemberships = membershipsWithPlan.filter(
    (m): m is StudioMembership => m !== null
  )

  if (validMemberships.length === 0) {
    throw new NoStudioMembershipError()
  }

  // 4. Resolve active studio from cookie
  const cookieStore = await cookies()
  const cookieValue = cookieStore.get('inkos_active_studio')?.value

  let resolved: StudioMembership | undefined

  if (cookieValue) {
    // Validate cookie value against actual memberships (defence-in-depth)
    resolved = validMemberships.find((m) => m.studioId === cookieValue)
    if (!resolved) {
      // Cookie holds a studio the user no longer belongs to — clear it
      // (Can't set cookies in layout Server Component; the route handler will clear it.
      //  Fall back silently here to the first membership.)
    }
  }

  // 5. Fallback to first membership
  if (!resolved) {
    resolved = validMemberships[0]
  }

  // validMemberships.length > 0 is guaranteed above (would have thrown otherwise)
  // resolved is now definitely defined
  const activeStudio = resolved as StudioMembership

  return {
    studioId: activeStudio.studioId,
    studio: activeStudio.studio,
    role: activeStudio.role,
    plan: activeStudio.plan,
    allMemberships: validMemberships,
  }
}

