/**
 * React `cache()` wraps the fetcher so any Server Component in the same request
 * that calls `getActiveStudio()` after the layout already did hits an in-memory
 * cache instead of re-querying Supabase. The cached value is scoped to a single
 * request; no cross-request sharing.
 */
export const getActiveStudio = cache(_getActiveStudio)

async function _getActiveStudio(): Promise<ActiveStudioContext> {
  const supabase = await createClient()

  // 1. Identify current user
  const {
    data: { user },
    error: authError,
  } = await supabase.auth.getUser()
  if (authError || !user) {
    throw new NoStudioMembershipError()
  }

  // 2. Fetch all memberships with studio data, ordered by created_at ASC
  const { data: rows, error: memberError } = await supabase
    .from('studio_members')
    .select(
      `
      studio_id,
      role,
      created_at,
      studios (
        id, name, slug, timezone, locale, currency, brand_color, logo_url, plan_id,
        custom_domain, custom_domain_verified, custom_domain_verified_at,
        white_label_enabled, custom_favicon_url, custom_email_from_name,
        custom_email_reply_to, powered_by_hidden, status, created_at, updated_at
      )
      `
    )
    .eq('user_id', user.id)
    .is('deactivated_at', null)
    .order('created_at', { ascending: true })

  if (memberError || !rows || rows.length === 0) {
    throw new NoStudioMembershipError()
  }

  // 3. S19 perf — batch subscription lookup (was N+1 per studio). Single query
  //    returns all active subs for the user's studios; we map locally.
  const studioIds = rows
    .map((r) => r.studio_id)
    .filter((id): id is string => Boolean(id))

  const planByStudio = new Map<string, PlanTier>()
  if (studioIds.length > 0) {
    const { data: subs } = await supabase
      .from('subscriptions')
      .select('studio_id, plan_tier')
      .in('studio_id', studioIds)
      .eq('status', 'active')
    for (const s of subs ?? []) {
      if (s.plan_tier) planByStudio.set(s.studio_id, s.plan_tier as PlanTier)
    }
  }

  const validMemberships: StudioMembership[] = []
  for (const row of rows) {
    const studio = (
      Array.isArray(row.studios) ? row.studios[0] : row.studios
    ) as StudioRow | null
    if (!studio) continue // Edge: studio row deleted but membership exists — skip gracefully

    validMemberships.push({
      studioId: row.studio_id,
      studio,
      role: row.role as StudioMemberRole,
      plan: planByStudio.get(row.studio_id) ?? 'solo',
    })
  }

