'use client'

import * as React from 'react'
import { Eye, EyeOff } from 'lucide-react'
import { Input } from '@/components/ui/input'
import { cn } from '@/lib/utils'

type PasswordInputProps = Omit<React.ComponentProps<'input'>, 'type'>

/**
 * Password field with a show/hide toggle. Matches the Brand Book v1.0 Input
 * visual (same height, radius, focus ring) and keeps the eye-button inside
 * the input bounds for a clean single-field feel.
 *
 * Accessibility:
 *  - Toggle is a real <button> with aria-pressed + aria-label that switches
 *    between "Show password" and "Hide password"
 *  - Tab order: input → toggle (natural)
 *  - Does not trigger the form's submit on click (type="button")
 */
const PasswordInput = React.forwardRef<HTMLInputElement, PasswordInputProps>(
  function PasswordInput({ className, ...props }, ref) {
    const [visible, setVisible] = React.useState(false)

    return (
      <div className="relative">
        <Input
          ref={ref}
          type={visible ? 'text' : 'password'}
          className={cn('pr-10', className)}
          {...props}
        />
        <button
          type="button"
          onClick={() => setVisible((v) => !v)}
          aria-pressed={visible}
          aria-label={visible ? 'Hide password' : 'Show password'}
          className={cn(
            'absolute inset-y-0 right-0 flex w-10 items-center justify-center',
            'text-muted-foreground/70 transition-colors',
            'hover:text-foreground focus:text-foreground',
            'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/50 focus-visible:ring-offset-0',
            'rounded-r-lg',
          )}
          tabIndex={0}
        >
          {visible ? (
            <EyeOff className="h-4 w-4" aria-hidden="true" />
          ) : (
            <Eye className="h-4 w-4" aria-hidden="true" />
          )}
        </button>
      </div>
    )
  },
)

export { PasswordInput }
export type { PasswordInputProps }

