'use client'

import { useState } from 'react'
import { useRouter, useSearchParams } from 'next/navigation'
import { useKeyboardAware } from '@/hooks/useKeyboardAware'
import Link from 'next/link'
import { Typography } from '@/components/ui/typography'
import { zodResolver } from '@hookform/resolvers/zod'
import { useForm } from 'react-hook-form'
import { z } from 'zod'
import { ArrowRight, CheckCircle2, Mail } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { PasswordInput } from '@/components/ui/password-input'
import { createClient } from '@/lib/supabase/client'

const loginSchema = z.object({
  email: z.string().email('Enter a valid email'),
  password: z.string().min(8, 'Password must be at least 8 characters'),
})

type LoginValues = z.infer<typeof loginSchema>

/**
 * Resolve a safe post-login redirect target. Must be a relative path with no
 * protocol or protocol-relative double-slash to block open-redirect attacks.
 */
function safeRedirectTarget(raw: string | null): string {
  if (!raw) return '/dashboard'
  if (!raw.startsWith('/')) return '/dashboard'
  if (raw.startsWith('//') || raw.includes(':')) return '/dashboard'
  return raw
}

export function LoginForm() {
  useKeyboardAware()
  const router = useRouter()
  const searchParams = useSearchParams()

  const [isSubmitting, setIsSubmitting] = useState(false)
  const [googleLoading, setGoogleLoading] = useState(false)
  const [magicLoading, setMagicLoading] = useState(false)
  const [errorMessage, setErrorMessage] = useState<string>('')

  // Magic-link post-submit confirmation state
  const [magicSentTo, setMagicSentTo] = useState<string | null>(null)
  const [magicCooldown, setMagicCooldown] = useState(0)

  const {
    register,
    handleSubmit,
    getValues,
    formState: { errors },
  } = useForm<LoginValues>({
    resolver: zodResolver(loginSchema),
  })

  const onSubmit = handleSubmit(async (values) => {
    setIsSubmitting(true)
    setErrorMessage('')

    const supabase = createClient()
    const { error } = await supabase.auth.signInWithPassword({
      email: values.email,
      password: values.password,
    })

    if (error) {
      setIsSubmitting(false)
      setErrorMessage('Incorrect email or password')
      return
    }

    const redirectTo = safeRedirectTarget(searchParams.get('redirectedFrom'))
    router.push(redirectTo)
    router.refresh()
  })

  async function handleGoogleSignIn() {
    setGoogleLoading(true)
    setErrorMessage('')
    const supabase = createClient()
    const appUrl = process.env.NEXT_PUBLIC_APP_URL ?? window.location.origin
    const { error } = await supabase.auth.signInWithOAuth({
      provider: 'google',
      options: { redirectTo: `${appUrl}/callback` },
    })
    if (error) {
      setGoogleLoading(false)
      setErrorMessage(`Couldn't start Google sign-in — try again`)
    }
    // On success the browser navigates away; no state cleanup needed.
  }

  async function handleMagicLink() {
    const email = getValues('email')
    const emailValidation = z.string().email().safeParse(email)
    if (!emailValidation.success) {
      setErrorMessage('Enter your email above first, then tap the link option.')
      return
    }

    setMagicLoading(true)
    setErrorMessage('')

    const supabase = createClient()
    const appUrl = process.env.NEXT_PUBLIC_APP_URL ?? window.location.origin
    const { error } = await supabase.auth.signInWithOtp({
      email,
      options: { emailRedirectTo: `${appUrl}/callback` },
    })

    setMagicLoading(false)

    if (error) {
      setErrorMessage(`Couldn't send sign-in link — try again`)
      return
    }

    setMagicSentTo(email)
    startMagicCooldown()
  }

  function startMagicCooldown() {
    setMagicCooldown(60)
    const interval = window.setInterval(() => {
      setMagicCooldown((prev) => {
        if (prev <= 1) {
          window.clearInterval(interval)
          return 0
        }
        return prev - 1
      })
    }, 1000)
  }

  // Confirmation screen — shown after a successful magic-link send
  if (magicSentTo) {
    return (
      <div className="space-y-6 text-center">
        <div className="mb-1 flex justify-center">
          <div className="flex h-12 w-12 items-center justify-center rounded-full bg-primary/10">
            <CheckCircle2 className="h-6 w-6 text-primary" aria-hidden="true" />
          </div>
        </div>
        <div className="space-y-1">
          <Typography variant="h1" className="leading-tight">
            Check your inbox
          </Typography>
          <p className="text-sm text-muted-foreground">We sent a sign-in link to</p>
          <p className="text-sm font-semibold text-foreground">{magicSentTo}</p>
        </div>
        <div className="space-y-2">
          <Button
            type="button"
            variant="outline"
            className="w-full h-10"
            disabled={magicCooldown > 0 || magicLoading}
            onClick={() => void handleMagicLink()}
          >
            {magicCooldown > 0 ? `Resend in ${magicCooldown}s` : 'Resend link'}
          </Button>
          <Button
            type="button"
            variant="ghost"
            className="w-full h-10"
            onClick={() => setMagicSentTo(null)}
          >
            ← Use a different method
          </Button>
        </div>
      </div>
    )
  }

  return (
    <form onSubmit={onSubmit} noValidate className="space-y-5">
      {/* Heading */}
      <div className="space-y-1">
        <Typography variant="h1" className="leading-tight">
          Welcome back
        </Typography>
        <p className="text-sm text-muted-foreground">Sign in to your studio</p>
      </div>

      {/* Google OAuth — primary/first for mobile-first conversion */}
      <Button
        type="button"
        variant="outline"
        className="w-full h-11 font-medium"
        onClick={() => void handleGoogleSignIn()}
        loading={googleLoading}
        loadingLabel="Opening Google…"
        aria-label="Continue with Google"
      >
        <GoogleIcon />
        Continue with Google
      </Button>

      {/* Divider */}
      <div className="relative">
        <div className="absolute inset-0 flex items-center">
          <span className="w-full border-t border-border" />
        </div>
        <div className="relative flex justify-center">
          <span className="bg-card px-3 text-xs text-muted-foreground">or continue with email</span>
        </div>
      </div>

      {/* Email */}
      <div className="space-y-1.5">
        <Label htmlFor="email">Email</Label>
        <Input
          id="email"
          type="email"
          autoComplete="email"
          placeholder="you@studio.com"
          aria-describedby={errors.email ? 'email-error' : undefined}
          aria-invalid={!!errors.email}
          {...register('email')}
        />
        {errors.email && (
          <p id="email-error" role="alert" className="text-xs text-destructive">
            {errors.email.message}
          </p>
        )}
      </div>

      {/* Password */}
      <div className="space-y-1.5">
        <div className="flex items-center justify-between">
          <Label htmlFor="password">Password</Label>
          <Link
            href="/forgot-password"
            className="text-xs text-primary underline-offset-2 hover:underline"
          >
            Forgot password?
          </Link>
        </div>
        <PasswordInput
          id="password"
          autoComplete="current-password"
          aria-describedby={errors.password ? 'password-error' : undefined}
          aria-invalid={!!errors.password}
          {...register('password')}
        />
        {errors.password && (
          <p id="password-error" role="alert" className="text-xs text-destructive">
            {errors.password.message}
          </p>
        )}
      </div>

      {/* Inline auth error (password / oauth / magic-link) */}
      {errorMessage && (
        <p role="alert" className="text-sm text-destructive">
          {errorMessage}
        </p>
      )}

      {/* Primary CTA */}
      <Button
        type="submit"
        className="w-full h-11 font-semibold"
        loading={isSubmitting}
        loadingLabel="Signing in…"
      >
        Sign in
        <ArrowRight className="ml-1.5 h-4 w-4" aria-hidden="true" />
      </Button>

      {/* Magic-link alt — subtle secondary option */}
      <button
        type="button"
        onClick={() => void handleMagicLink()}
        disabled={magicLoading}
        className="flex w-full items-center justify-center gap-1.5 text-xs text-muted-foreground transition-colors hover:text-foreground disabled:cursor-not-allowed disabled:opacity-50"
      >
        <Mail className="h-3.5 w-3.5" aria-hidden="true" />
        {magicLoading ? 'Sending link…' : 'Email me a sign-in link instead'}
      </button>

      {/* Footer — new-user CTA */}
      <p className="pt-1 text-center text-sm text-muted-foreground">
        New to InkOS?{' '}
        <Link
          href="/signup"
          className="font-medium text-primary underline-offset-2 hover:underline"
        >
          Start free trial
        </Link>
      </p>
    </form>
  )
}

function GoogleIcon() {
  return (
    <svg className="mr-2 h-4 w-4" viewBox="0 0 24 24" aria-hidden="true">
      <path
        d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92c-.26 1.37-1.04 2.53-2.21 3.31v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.09z"
        fill="#4285F4"
      />
      <path
        d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z"
        fill="#34A853"
      />
      <path
        d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l2.85-2.22.81-.62z"
        fill="#FBBC05"
      />
      <path
        d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z"
        fill="#EA4335"
      />
    </svg>
  )
}

