'use client'

import { useState } from 'react'
import Link from 'next/link'
import { Typography } from '@/components/ui/typography'
import { zodResolver } from '@hookform/resolvers/zod'
import { useForm } from 'react-hook-form'
import { z } from 'zod'
import { ArrowRight, CheckCircle2 } from 'lucide-react'
import { toast } from 'sonner'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'

const forgotSchema = z.object({
  email: z.string().email('Enter a valid email'),
})

type ForgotValues = z.infer<typeof forgotSchema>

export function ForgotPasswordForm() {
  const [isSent, setIsSent] = useState(false)
  const [sentEmail, setSentEmail] = useState('')
  const [isSubmitting, setIsSubmitting] = useState(false)
  const [cooldown, setCooldown] = useState(0)

  const {
    register,
    handleSubmit,
    getValues,
    formState: { errors },
  } = useForm<ForgotValues>({
    resolver: zodResolver(forgotSchema),
  })

  function startCooldown() {
    setCooldown(60)
    const interval = window.setInterval(() => {
      setCooldown((prev) => {
        if (prev <= 1) {
          window.clearInterval(interval)
          return 0
        }
        return prev - 1
      })
    }, 1000)
  }

  async function sendReset(email: string): Promise<boolean> {
    setIsSubmitting(true)

    const res = await fetch('/api/auth/forgot-password', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ email }),
    })

    setIsSubmitting(false)

    if (!res.ok) {
      toast.error(`Couldn't send reset link — try again`)
      return false
    }

    return true
  }

  const onSubmit = handleSubmit(async (values) => {
    const success = await sendReset(values.email)
    if (success) {
      setSentEmail(values.email)
      setIsSent(true)
      startCooldown()
    }
  })

  async function handleResend() {
    if (cooldown > 0) return
    const email = getValues('email') || sentEmail
    const success = await sendReset(email)
    if (success) {
      toast.success('Reset link sent again')
      startCooldown()
    }
  }

  // Confirmation screen
  if (isSent) {
    return (
      <div className="space-y-6 text-center">
        <div className="flex justify-center">
          <div className="flex h-12 w-12 items-center justify-center rounded-full bg-primary/10">
            <CheckCircle2 className="h-6 w-6 text-primary" aria-hidden="true" />
          </div>
        </div>
        <div className="space-y-1">
          <Typography variant="h1" className="leading-tight">
            Check your inbox
          </Typography>
          <p className="text-sm text-muted-foreground">We sent a reset link to</p>
          <p className="text-sm font-semibold text-foreground">{sentEmail}</p>
        </div>

        <div className="space-y-2">
          <Button
            type="button"
            variant="outline"
            className="w-full h-10"
            disabled={cooldown > 0 || isSubmitting}
            onClick={() => void handleResend()}
          >
            {cooldown > 0 ? `Resend in ${cooldown}s` : 'Resend link'}
          </Button>
          <Button
            type="button"
            variant="ghost"
            className="w-full h-10"
            render={<Link href="/login" />}
          >
            ← Back to sign in
          </Button>
        </div>
      </div>
    )
  }

  return (
    <form onSubmit={onSubmit} noValidate className="space-y-5">
      {/* Heading */}
      <div className="space-y-1">
        <Typography variant="h1" className="leading-tight">
          Reset your password
        </Typography>
        <p className="text-sm text-muted-foreground">
          We&apos;ll email you a secure link.
        </p>
      </div>

      {/* Email */}
      <div className="space-y-1.5">
        <Label htmlFor="email">Email</Label>
        <Input
          id="email"
          type="email"
          autoComplete="email"
          placeholder="you@studio.com"
          aria-describedby={errors.email ? 'email-error' : undefined}
          aria-invalid={!!errors.email}
          {...register('email')}
        />
        {errors.email && (
          <p id="email-error" role="alert" className="text-xs text-destructive">
            {errors.email.message}
          </p>
        )}
      </div>

      {/* Submit */}
      <Button
        type="submit"
        className="w-full h-11 font-semibold"
        loading={isSubmitting}
        loadingLabel="Sending link…"
      >
        Send reset link
        <ArrowRight className="ml-1.5 h-4 w-4" aria-hidden="true" />
      </Button>

      {/* Back link */}
      <p className="pt-1 text-center text-sm text-muted-foreground">
        Remembered your password?{' '}
        <Link
          href="/login"
          className="font-medium text-primary underline-offset-2 hover:underline"
        >
          Sign in
        </Link>
      </p>
    </form>
  )
}

