if (service_ids) {
  const ids = service_ids.split(',').filter(Boolean)
  if (ids.length > 0) {
    const { data: serviceClientIds } = await supabase
      .from('bookings')
      .select('client_id')
      .eq('studio_id', authUser.studioId)
      .in('service_id', ids)
    if (serviceClientIds && serviceClientIds.length > 0) {
      mergeFilteredClientIds(serviceClientIds.map((r) => r.client_id).filter(Boolean) as string[])
    } else {
      return NextResponse.json({ data: [], count: 0, page, per_page, total_pages: 0 })
    }
  }
}

// Health alert filter — aligns with the existing red badge behavior.
if (has_alerts) {
  const { data: alertRows, error } = await rawQuery<Pick<ClientHealthSummaryRow, 'client_id'>>(
    supabase,
    'client_health_summary',
  )
    .select('client_id')
    .eq('studio_id', authUser.studioId)
    .gt('critical_pinned_count', 0)

  if (error) {
    logger.error({ err: error, studioId: authUser.studioId }, 'client alert filter failed')
    return NextResponse.json({ error: 'Failed to fetch clients' }, { status: 500 })
  }

  const alertClientIds = (alertRows ?? []).map((row) => row.client_id).filter(Boolean)
  if (alertClientIds.length === 0) {
    return NextResponse.json({ data: [], count: 0, page, per_page, total_pages: 0 })
  }
  mergeFilteredClientIds(alertClientIds)
}

if (hasFilteredClientIds) {
  if (filteredClientIds.length === 0) {
    return NextResponse.json({ data: [], count: 0, page, per_page, total_pages: 0 })
